export type ReleaseBranch = "stable" | "testing" | "unstable";
export type Architecture = "amd64" | "arm64" | "i386" | "ppc64el" | "riscv64";
export type Media = "netinst" | "gnome" | "kde" | "xfce";

export type DownloadConfig = {
  branch: ReleaseBranch;
  architecture: Architecture;
  media: Media;
};

const releaseVersions: Record<ReleaseBranch, string> = {
  stable: "12.5.0",
  testing: "trixie-DI-alpha",
  unstable: "sid-daily",
};

export function getIsoFilename({
  branch,
  architecture,
  media,
}: DownloadConfig): string {
  return `debian-${releaseVersions[branch]}-${architecture}-${media}.iso`;
}

export function getMediaDescription(media: Media): string {
  return media === "netinst"
    ? "~628 MB • Minimal Netinstall ISO"
    : "~3.4 GB • Live ISO with GUI Desktop";
}
